from pathlib import Path

import pytest

from shab_analyzer.config import PARSER_VERSION
from shab_analyzer.parse import parse_publication_xml

FIXTURES = Path(__file__).parent / "fixtures"


def _parse(stem: str):
    return parse_publication_xml(FIXTURES / f"{stem}.xml", publication_id=stem)


def test_acoutech_seat_address_and_persons():
    result = _parse("fff92f73-ab6f-4772-ab5a-bd08831dddc5")
    types = {e.event_type for e in result.events}
    assert "seat_changed" in types
    assert "address_changed" in types
    assert result.canton == "ZG"
    assert result.plz == "6340"
    assert result.org_uid == "CHE-110.028.408"
    persons = [e for e in result.events if e.person_key]
    assert any("heck" in (e.person_key or "") and e.signing for e in persons)
    assert any("uid:CHE-343.667.148" == e.person_key for e in persons)
    assert any(e.event_type == "statutes_changed" and e.payload.get("date") == "2026-08-28" for e in result.events)


