def test_de_two_person_sections_removed_and_added():
    result = _parse("a3d86d90-4b95-4f57-8a98-d70ad9dbdf05")
    keys = {e.person_key for e in result.events if e.person_key}
    assert any("yilmaz" in (k or "") for k in keys)
    assert any("pusat" in (k or "") for k in keys)
    assert any(e.event_type == "officer_removed" for e in result.events)
    assert any(e.event_type == "officer_changed" for e in result.events)
    yilmaz = next(e for e in result.events if e.event_type == "officer_removed")
    pusat = next(e for e in result.events if e.event_type == "officer_changed")
    assert yilmaz.payload["shares_count"] == 100
    assert pusat.payload["shares_count"] == 200
    assert "100 Stammanteilen" in (pusat.payload.get("previous") or "")


