    removed = {e.payload.get("name") for e in board.events if e.event_type == "officer_removed"}
    assert removed == {"Eder James A.", "Büchler Frédéric"}
    assert any(
        e.payload.get("name") == "Munsch Lionel"
        and e.payload.get("action") == "revoked"
        for e in board.events
    )
    assert any(
        e.payload.get("name") == "Veignat Norbert" and e.signing == "Einzelunterschrift"
        for e in board.events
    )
    assert {"Deegan Glenn Edward", "Patriacca Todd Brooks"} <= {
        e.payload.get("name") for e in board.events
    }

    court = _parse("86dc7dc7-1a48-4a54-ace0-edfa6b33db67")
    revoked = next(e for e in court.events if e.payload.get("name") == "Claudia Bögli")
    granted = next(
        e
        for e in court.events
        if e.payload.get("name") == "Rehle Gina" and e.event_type == "signing_authority_changed"
    )
    corrected = next(e for e in court.events if e.rule_id == "de.persons.name_correction.v1")
    assert revoked.payload["action"] == "revoked"
    assert granted.signing == "Einzelunterschrift"
    assert corrected.payload["previous"] == "Strehle Gina"


