def test_parser_25_person_variants():
    baeriswyl = _parse("5acde748-ca9e-4a9d-b162-59375b518829")
    person = next(e for e in baeriswyl.events if e.event_type == "officer_changed")
    assert person.payload["name"] == "Baeriswyl Priska"
    assert person.payload["heimat"] == "Alterswil"
    assert person.role == "Mitglied der Geschäftsleitung"
    assert person.signing == "Kollektivunterschrift zu zweien"

    young = _parse("15081052-58dc-4d8d-8800-5c51bdd06d38")
    manager = next(e for e in young.events if e.event_type == "officer_changed")
    assert manager.payload["name"] == "Young Micah Wesley"
    assert manager.payload["place"] == "Vista, CA, USA"
    assert manager.role == "gérant"
    assert manager.signing == "Einzelunterschrift"

    martin = _parse("41366217-d4f5-4b27-8d0f-5319dff7d78e")
    president = next(e for e in martin.events if e.event_type == "officer_changed")
    assert president.payload["name"] == "Martin Philippe"
    assert president.role == "gérant et président"
    assert president.signing == "Einzelunterschrift"

    elected = _parse("0aa9a6a4-ff0c-4a25-bb79-2107ad6f14b9")
    elected_by_name = {e.payload["name"]: e for e in elected.events}
    assert elected_by_name["Delarive Patrick"].role == "président"
    assert elected_by_name["Delarive Patrick"].payload["previous"] == "administrateur"
    assert elected_by_name["Bourachot Florent"].role == "administrateur"

