def test_parser_43_share_transfers_and_holdings():
    transfer = _parse("0353f029-8ef2-44d3-8141-a15c09651624")
    associates = {
        event.payload["name"]: event
        for event in transfer.events
        if event.rule_id == "fr.persons.associate_transfer_triple.v1"
    }
    assert associates["Goubin Stéphane"].payload["previous_shares_count"] == 150
    assert associates["Goubin Stéphane"].payload["shares_transferred"] == 10
    assert associates["Goubin Stéphane"].payload["shares_count"] == 140
    assert associates["Schorderet Nicolas"].payload["shares_count"] == 20
    assert associates["Addor Philippe"].payload["shares_count"] == 20
    buyer = associates["Desénépart Bertrand"]
    assert buyer.payload["place"] == "Pully"
    assert buyer.payload["shares_count"] == 20
    assert buyer.payload["without_signature"] is True

    holdings = _parse("f58c987f-feec-4ed5-979c-11bbd3d02a90")
    capital = next(
        event
        for event in holdings.events
        if event.rule_id == "fr.text.social_capital_composition.v1"
    )
    assert capital.payload["total"] == "250'000"
    assert capital.payload["shares_count"] == 250
    assert capital.payload["shares_nominal"] == "1'000"
    owners = {
        event.payload["name"]: event.payload["shares_count"]
        for event in holdings.events
        if event.rule_id == "fr.persons.shareholding_now_pair.v1"
    }
    assert owners == {"Roch Armand": 249, "Roch Marie Josée": 1}
    assert any(
        event.rule_id == "fr.text.contribution_rules_removed.v1"
        for event in holdings.events
    )


