def test_parser_50_french_person_and_share_variants():
    administration = [
        event
        for event in _parse("5d8e0ccb-8eaa-4123-b3ea-4cf2caae6005").events
        if event.rule_id == "fr.persons.administration_pair.v3"
    ]
    assert {event.payload["name"] for event in administration} == {
        "Bordera Pascual",
        "Banet Joël Robert",
    }
    assert all(event.signing == "Einzelunterschrift" for event in administration)
    assert next(
        event for event in administration if event.payload["name"] == "Bordera Pascual"
    ).role == "président"

    director = next(
        event
        for event in _parse("6fee9723-ed12-48e3-8b07-3ae8ab9acf84").events
        if event.event_type == "officer_changed"
        and event.rule_id == "fr.persons.appointed_signing.v2"
    )
    assert director.payload["name"] == "De Wilde Séverine"
    assert director.role == "directrice"
    assert director.signing == "Kollektivunterschrift zu zweien"
    assert director.payload["procuration_revoked"] is True

    share_result = _parse("8ead4b54-bfe8-4143-a473-adfd379795cb")
    capital = next(
        event
        for event in share_result.events
        if event.rule_id == "fr.text.social_capital_composition.v2"
    )
    assert capital.payload["holder"] == "Ringger Sven"
    assert capital.payload["share_classes"] == [
        {"count": 100, "nominal": "100", "rights": "privilégiées quant au droit de vote"},
        {"count": 20, "nominal": "500"},
    ]
    associates = [
        event
        for event in share_result.events
        if event.rule_id == "fr.persons.associate_multi_class_transfer.v1"
    ]
    assert {event.payload["name"] for event in associates} == {
        "Ringger Sven",
        "Theler Julien",
    }
    buyer = next(event for event in associates if event.payload["name"] == "Theler Julien")
    assert buyer.payload["without_signature"] is True
    assert buyer.payload["share_classes"][0]["count"] == 10


