def test_parser_62_mixed_language_people_are_structured():
    german = [
        event
        for event in _parse("000aaf64-9fff-4d8f-a879-58cb69b9fe2b").events
        if event.rule_id == "de.persons.mixed_language_new_person.v1"
    ]
    assert {event.payload["name"] for event in german} == {
        "Jain Neeraj",
        "Vogel Alexander Peter Cornelius",
    }
    assert all(event.role == "Verwaltungsratsmitglied" for event in german)
    assert all(event.signing == "Kollektivunterschrift zu zweien" for event in german)
    vogel = next(event for event in german if event.payload["name"].startswith("Vogel"))
    assert vogel.payload["heimat"] == "Zürich"

    administration = [
        event
        for event in _parse("01056152-7c02-4f4f-84f5-7ad75f9a0523").events
        if event.rule_id == "fr.persons.administration_pair.v1"
    ]
    assert {(event.payload["name"], event.role) for event in administration} == {
        ("Hoving Michael", "président"),
        ("Stresemann Walter", "administrateur"),
    }
    assert all(event.signing == "Einzelunterschrift" for event in administration)
    stresemann = next(
        event for event in administration if event.payload["name"] == "Stresemann Walter"
    )
    assert stresemann.payload["heimat"] == "Fontenais"
    assert stresemann.payload["place"] == "Grand-Saconnex"

    committee = [
        event
        for event in _parse("22e8bec4-dae5-42fa-b075-e61f62701eb1").events
        if event.rule_id == "fr.persons.committee_group.v1"
    ]
    assert {event.payload["name"] for event in committee} == {
        "Sima Hailegiyorgis",
        "Gezahegn Baheru",
        "Balcha Tilahun Hana",
    }
    unsigned = next(
        event for event in committee if event.payload["name"] == "Balcha Tilahun Hana"
    )
    assert unsigned.payload["without_signature"] is True


