def test_parser_64_people_and_share_transfers_are_structured():
    company_transfer = [
        event
        for event in _parse("1c433733-bb11-455c-aca8-91db70abceb4").events
        if event.rule_id == "fr.persons.associate_transfer_to_company.v1"
    ]
    assert {event.payload["name"] for event in company_transfer} == {
        "Ganci Vincenzo",
        "UMEO Holding SA",
    }
    buyer = next(event for event in company_transfer if event.payload["name"] == "UMEO Holding SA")
    assert buyer.person_key == "uid:CHE-136.380.344"
    assert buyer.payload["uid"] == "CHE-136.380.344"
    assert buyer.payload["shares_count"] == 200

    appointed = next(
        event
        for event in _parse("1d243bf0-d725-4e7c-b4b1-aec275681f96").events
        if event.rule_id == "fr.persons.associate_appointed_manager.v1"
    )
    assert appointed.payload["name"] == "Montaldo Giorgio"
    assert appointed.role == "gérant"
    assert appointed.signing == "Einzelunterschrift"

    group_transfer = [
        event
        for event in _parse("2936f18e-0fc6-4a46-b839-704c053b8b25").events
        if event.rule_id == "fr.persons.associates_removed_transfer.v1"
    ]
    assert {event.payload["name"] for event in group_transfer} == {
        "Koroli Valon",
        "Béroud Olivier",
        "Valdez De Los Santos Miguel",
    }
    assert sum(event.event_type == "officer_removed" for event in group_transfer) == 2

    corrected = next(
        event
        for event in _parse("2a1190a5-c2c9-42ac-b47d-c78fec305586").events
        if event.rule_id == "fr.persons.role_corrected.v1"
    )
    assert corrected.payload["name"] == "Mojon Gérard"
    assert corrected.role == "gérant"
    assert corrected.payload["previous_role"] == "président"

    vice_president = next(
        event
        for event in _parse("7a678ca0-e3ee-4f1e-9e20-83be6a501986").events
        if event.rule_id == "fr.persons.compact_appointment.v1"
    )
    assert vice_president.payload["name"] == "Boiron Henri"
    assert vice_president.role == "vice-président"


