def test_parser_65_people_share_and_branch_events_are_structured():
    managers = [
        event
        for event in _parse("0f434e39-ee3e-4db9-a376-b3a61df6f59d").events
        if event.rule_id == "fr.persons.managers_pair.v1"
    ]
    assert {(event.payload["name"], event.role) for event in managers} == {
        ("Dougoud Jean Claude", "président"),
        ("Luca Lara Concetta", "gérant"),
    }
    assert all(event.signing == "Einzelunterschrift" for event in managers)

    administration = [
        event
        for event in _parse("1dac784f-7a78-45e2-8654-0ac527fd6be5").events
        if event.rule_id == "fr.persons.administration_pair_move.v1"
    ]
    assert {(event.payload["name"], event.role) for event in administration} == {
        ("Hayoun Patrick", "président"),
        ("Zuanon Sergio", "secrétaire"),
    }
    assert next(
        event for event in administration if event.payload["name"] == "Hayoun Patrick"
    ).payload["country"] == "EAU"

    transfers = [
        event
        for event in _parse("2c967280-155f-49cd-9c8d-8ca6d6e24b6f").events
        if event.rule_id == "fr.persons.associate_transfer_remainder.v1"
    ]
    seller = next(event for event in transfers if event.payload["name"] == "Tournon Paolo Tommaso")
    buyer = next(event for event in transfers if event.payload["name"] == "Ganz Abel Paul Gildas")
    assert seller.payload["shares_before"] == 27
    assert seller.payload["shares_count"] == 18
    assert buyer.payload["shares_received"] == 9

    branches = [
        event
        for event in _parse("2f8c8c4e-74b2-4a4d-86b0-284ec75e0eca").events
        if event.rule_id == "fr.text.branch_added_continuation.v1"
    ]
    assert {(event.payload["place"], event.payload["branch_uid"]) for event in branches} == {
        ("Emmen", "CHE-321.654.278"),
        ("Frauenfeld", "CHE-337.864.410"),
    }

    liquidator = next(
        event
        for event in _parse("b8cdc626-fd79-4cb1-a954-0350570ddcc0").events
        if event.rule_id == "fr.persons.liquidator_after_conversion.v1"
    )
    assert liquidator.payload["name"] == "Gruhn Patrick"
    assert liquidator.payload["place"] == "Saint-Légier-La Chiésaz"
    assert liquidator.role == "liquidateur"


