def test_parser_67_people_and_share_transfers_are_structured():
    same_place = [
        event
        for event in _parse("5396b069-7836-4ca8-9f90-8f44bf1a8631").events
        if event.rule_id == "fr.persons.administration_pair_same_place.v1"
    ]
    assert {(event.payload["name"], event.role) for event in same_place} == {
        ("Buchs Jean-Bernard", "président"),
        ("Echeverria Falla Manuel José", "administrateur"),
    }
    assert all(event.signing == "Einzelunterschrift" for event in same_place)

    administration = [
        event
        for event in _parse("54c74daa-1688-43fc-9de3-fcf9cda89f35").events
        if event.rule_id == "fr.persons.administration_moved_president_pair.v1"
    ]
    assert {event.payload["name"] for event in administration} == {
        "Lakhbabi Dalila",
        "El Hajri Said",
    }
    assert all(event.signing == "Einzelunterschrift" for event in administration)

    unsigned = [
        event
        for event in _parse("558da0b1-f4e3-4800-b808-ccd45ede1b7a").events
        if event.rule_id == "fr.persons.foundation_members_without_signing.v1"
    ]
    assert {event.payload["name"] for event in unsigned} == {
        "Fraiberger Vanessa",
        "Lembo Saverio",
    }
    assert all(event.payload["without_signature"] is True for event in unsigned)

    dual_transfer = [
        event
        for event in _parse("56d5798e-9262-4c24-966f-98f30007cde1").events
        if event.rule_id == "fr.persons.associate_transfer_dual_appointments.v1"
    ]
    assert {(event.payload["name"], event.role, event.payload["shares_count"]) for event in dual_transfer} == {
        ("Tronchoni Eduardo", "président", 100),
        ("Tronchoni Anne-Dominique", "gérante", 100),
    }

    signing_pair = [
        event
        for event in _parse("5a0db610-a27e-4ba3-89e5-16ae9090f673").events
        if event.rule_id == "fr.persons.signing_granted_proxy_revoked_pair.v1"
    ]
    assert {event.payload["name"] for event in signing_pair} == {
        "Chuard Max",
        "Dempsey-Leclercq Deirdre",
    }
    assert all(event.payload["previous_signing_revoked"] is True for event in signing_pair)

    company_transfer = [
        event
        for event in _parse("5d63ebfe-ac9d-4f77-baa7-a7e2a648a20e").events
        if event.rule_id == "fr.persons.company_associate_transfer_to_manager.v1"
    ]
    seller = next(event for event in company_transfer if event.payload["name"] == "White Groupe SA")
    buyer = next(
        event for event in company_transfer if event.payload["name"] == "De Macedo Soares Nuno Micael"
    )
    assert seller.person_key == "uid:CHE-115.120.257"
    assert seller.payload["shares_count"] == 225
    assert buyer.role == "associé et gérant"
    assert buyer.payload["shares_count"] == 75


