    foundation = [
        event
        for event in _parse("e4198a89-36b8-4341-b852-f7deb3fdd102").events
        if event.rule_id == "fr.persons.foundation_members_without_signature.v1"
    ]
    assert len(foundation) == 2
    assert all(event.payload["without_signature"] is True for event in foundation)

    branches = [
        event
        for event in _parse("e441bb61-a4f9-414e-89a7-8e084be40eb7").events
        if event.rule_id == "fr.text.branch_added_continuation.v1"
    ]
    assert {(event.payload["place"], event.payload["branch_uid"]) for event in branches} == {
        ("Rapperswil-Jona", "CHE-445.093.514"),
        ("Spreitenbach", "CHE-342.463.732"),
        ("Vilters-Wangs", "CHE-188.569.469"),
    }


