def test_parser_83_bankruptcy_moratorium_and_capital_are_structured():
    bankruptcy = _parse("169c18ad-7ce3-4c34-b3b5-2bc0195fc99f")
    opened = next(
        event
        for event in bankruptcy.events
        if event.rule_id == "fr.text.company_bankruptcy_opened_by_default.v1"
    )
    suspended = next(
        event
        for event in bankruptcy.events
        if event.rule_id == "fr.text.bankruptcy_effect_suspended_after_default.v1"
    )
    assert opened.payload["effective_date"] == "2023-08-17"
    assert opened.payload["effective_time"] == "11:35"
    assert opened.payload["judgment_by_default"] is True
    assert suspended.payload["decision_date"] == "2023-08-22"
    assert suspended.payload["bankruptcy_date"] == "2023-08-17"

    moratorium = next(
        event
        for event in _parse("96e3babb-1ddc-4fa6-9c8d-e2ad83678098").events
        if event.rule_id == "de.text.definitive_moratorium_extended_by_decision.v1"
    )
    assert moratorium.payload["duration_months"] == 2
    assert moratorium.payload["until"] == "2018-12-05"
    assert moratorium.payload["authority"] == "Bezirksgericht Zürich"

    capital = next(
        event
        for event in _parse("911c6052-65c8-4c94-8925-32912ebb421c").events
        if event.rule_id == "de.text.nominal_reduction_with_distribution.v1"
    )
    assert capital.payload["shares_count"] == 1000
    assert capital.payload["from_nominal"] == "1'000.00"
    assert capital.payload["to_nominal"] == "100.00"
    assert capital.payload["cash_repayment"] == "300'000.00"
    assert capital.payload["shareholder_account_credit"] == "600'000.00"
    assert capital.payload["confirmation_date"] == "2018-08-27"


