def test_parser_86_share_transfers_are_structured():
    split = [
        event
        for event in _parse("67f58415-fd66-4202-b38d-839de035f00b").events
        if event.rule_id == "fr.persons.share_split_transfer_two_managers.v1"
    ]
    seller = next(event for event in split if event.payload["name"] == "Zanchetta Enio Daniel")
    president = next(event for event in split if event.payload["name"] == "Grimm Sonia Claire")
    manager = next(event for event in split if event.payload["name"] == "Tineo Steve Alban")
    assert seller.payload["shares_before"] == 180
    assert seller.payload["shares_transferred"] == 90
    assert seller.payload["shares_count"] == 90
    assert president.role == "associée-gérante présidente"
    assert president.payload["shares_count"] == 45
    assert president.payload["without_signature"] is True
    assert manager.payload["heimat"] == "Wengi"
    assert manager.payload["place"] == "Genève"

    joint = [
        event
        for event in _parse("c1c36757-43db-4db4-a81a-ec19332a1586").events
        if event.rule_id == "fr.persons.two_associates_transfer_to_manager.v1"
    ]
    buyer = next(event for event in joint if event.payload["name"] == "Marbe Vincent")
    sellers = [event for event in joint if event.payload["name"] != "Marbe Vincent"]
    assert buyer.payload["shares_received"] == 20
    assert buyer.payload["shares_count"] == 20
    assert buyer.signing == "Einzelunterschrift"
    assert {event.payload["shares_count"] for event in sellers} == {90}


