def test_parser_91_people_and_share_transfers_are_structured():
    organization_transfer = [
        event
        for event in _parse("21e34d9a-cc90-4c26-a244-cd035e461076").events
        if event.rule_id == "fr.persons.two_organizations_transfer_to_manager.v1"
    ]
    assert len(organization_transfer) == 3
    buyer = next(
        event for event in organization_transfer
        if event.payload["name"] == "Lichine Alexis"
    )
    assert buyer.payload["shares_received"] == 105
    assert buyer.payload["shares_count"] == 150
    assert buyer.payload["capital"] == "33'000"
    assert sum(
        event.payload["shares_transferred"]
        for event in organization_transfer
        if event.event_type == "officer_removed"
    ) == 105

    managers = [
        event
        for event in _parse("247b1ea4-0f68-4473-97f7-94ebd9bd0673").events
        if event.rule_id == "fr.persons.two_managers_individual_signing.v1"
    ]
    assert {event.payload["name"] for event in managers} == {
        "Peres Laurent",
        "Perez Avi",
    }
    assert all(event.signing == "Einzelunterschrift" for event in managers)
    assert next(event for event in managers if event.payload["name"] == "Perez Avi").role == (
        "gérant, président"
    )

    changed_people = [
        event
        for event in _parse("282fb5f5-55b1-4707-b271-b430af5c81ed").events
        if event.rule_id == "de.persons.removed_and_role_changed_plural.v1"
    ]
    assert {event.payload["name"] for event in changed_people} == {
        "Ebener Philippe",
        "Saner Andrea Dorothea",
    }
    saner = next(event for event in changed_people if event.payload["name"].startswith("Saner"))
    assert "vorsitzende Geschäftsführerin" in saner.payload["previous_role"]
    assert "Geschäftsführerin" in saner.role

    transfer = [
        event
        for event in _parse("2a1d3a53-91f1-4023-a77a-9a0e397c67f2").events
        if event.rule_id == "fr.persons.associate_transfer_new_associate.v2"
    ]
    assert next(event for event in transfer if event.payload["name"] == "Morand Steven").payload[
        "shares_count"
    ] == 11
    assert next(event for event in transfer if event.payload["name"] == "Veyrat Hakan").payload[
        "shares_count"
    ] == 9

    split_transfer = [
        event
        for event in _parse("b4f2ee08-ce8d-4199-918e-1231af3ad540").events
        if event.rule_id == "fr.persons.split_transfer_two_new_managers.v1"
    ]
    assert len(split_transfer) == 3
    assert next(
        event for event in split_transfer if event.payload["name"] == "Broillet Thomas"
    ).payload["shares_count"] == 13
    assert {
        event.payload["name"]: event.payload["shares_received"]
        for event in split_transfer
        if event.payload["name"] != "Broillet Thomas"
    } == {"Campanelli Bogat Jenny": 4, "Lanchas Thierry": 3}


