def test_parser_112_share_transfers_are_structured():
    director_transfer = [
        event for event in _parse("a65ccf44-8e6e-4155-83ef-1403f4ab330a").events
        if event.rule_id == "fr.persons.associate_manager_transfer_to_director.v1"
    ]
    irfan = next(event for event in director_transfer if event.payload["name"] == "Irfan Muhammad")
    khan = next(event for event in director_transfer if event.payload["name"] == "Khan Akram")
    assert irfan.payload["shares_count"] == 14
    assert irfan.payload["shares_transferred"] == 5
    assert khan.role == "associé-directeur"
    assert khan.payload["shares_count"] == 5
    assert khan.payload["heimat"] == "Pakistan"
    assert khan.payload["place"] == "Vernier"

    group_transfer = [
        event for event in _parse("a8baadbe-f7bb-4936-a627-dc4f2c67c90f").events
        if event.rule_id == "fr.persons.three_managers_transfer_to_associate_without_signature.v1"
    ]
    sellers = [event for event in group_transfer if event.role == "associé-gérant"]
    hoffmann = next(event for event in group_transfer if event.payload["name"] == "Hoffmann Stéphanie")
    assert len(sellers) == 3
    assert all(event.payload["shares_before"] == 120 for event in sellers)
    assert all(event.payload["shares_count"] == 117 for event in sellers)
    assert hoffmann.payload["shares_count"] == 9
    assert hoffmann.payload["without_signature"] is True

    two_buyers = [
        event for event in _parse("aaad7858-7396-42f1-a4fd-86beb326dc3c").events
        if event.rule_id == "fr.persons.manager_president_transfer_to_two_managers.v1"
    ]
    zahn = next(event for event in two_buyers if event.payload["name"] == "Zahn Olivier")
    assert zahn.role == "associé-gérant président"
    assert zahn.payload["shares_before"] == 200
    assert zahn.payload["shares_count"] == 194
    buyers = [event for event in two_buyers if event is not zahn]
    assert {event.payload["name"] for event in buyers} == {
        "Demolder Jean Baptiste", "Morel Sébastien"
    }
    assert all(event.payload["shares_count"] == 3 for event in buyers)


