def test_parser_123_share_transfers_are_structured():
    loca = _parser_123_events(
        "8294f206-c55f-4746-af17-e116db27b4ef",
        "fr.persons.manager_transfer_and_second_manager_appointed.v1",
    )
    drouhard = next(event for event in loca if event.payload["name"] == "Drouhard François-Régis")
    bulle = next(event for event in loca if event.payload["name"] == "Bulle Nicolas")
    reichenbach = next(event for event in loca if event.payload["name"] == "Reichenbach Michèle")
    assert drouhard.payload["previous_shares_count"] == 295
    assert drouhard.payload["shares_transferred"] == 75
    assert drouhard.payload["shares_count"] == 220
    assert bulle.payload["shares_received"] == 75
    assert reichenbach.role == "gérante"

    aquageo = _parser_123_events(
        "8715c7ea-f545-4004-bd30-5f633b027ba6",
        "fr.persons.two_managers_transfer_to_new_manager.v1",
    )
    matti = next(event for event in aquageo if event.payload["name"] == "Matti Boris Gérard")
    assert matti.payload["shares_received"] == 66
    assert matti.payload["shares_count"] == 66
    assert matti.role == "associé-gérant"
    assert {
        event.payload["shares_transferred"] for event in aquageo
        if event.payload["name"] != "Matti Boris Gérard"
    } == {23, 43}

    atelier = _parser_123_events(
        "88d949e9-f6d5-48bc-8c7b-542c13fa33f8",
        "fr.persons.share_transfer_to_new_sole_manager.v1",
    )
    gallay = next(event for event in atelier if event.payload["name"] == "Gallay André")
    robert = next(event for event in atelier if event.payload["name"] == "Robert Jean-Jacques")
    assert gallay.payload["shares_count"] == 190
    assert gallay.role == "associé-gérant unique"
    assert robert.payload["shares_count"] == 10


