    assert address.payload["entry_date"] == "2018-12-19"
    assert address.payload["to"] == "rue Eugène-Marziano 25, 1227 Les Acacias"
    assert address.payload["from"] == "avenue Eugène-Marziano 25"

    dissolution = _parser_134_events(
        "719ab81a-8f49-4645-8a9c-82c73d51fd3b",
        "de.text.dissolution_resolution_revoked.v1",
    )[0]
