def test_parser_134_audit_capital_and_statutes_changes_are_structured():
    correction = _parser_134_events(
        "760866a0-48f3-4f6c-bd0d-845abc8d4a4a",
        "de.text.audit_waiver_correction.v1",
    )[0]
    assert correction.payload["limited_audit_waived"] is False
    assert correction.payload["correction_reason"] == "system_error"
    assert correction.payload["declaration_date"] == "2009-06-05"
    assert correction.payload["entry_date"] == "2019-02-08"

    capital = _parser_134_events(
        "76089e30-6f15-4c3c-83e8-2a64e0ccf06a",
        "de.text.authorized_capital_two_decision_dates.v1",
    )[0]
    assert capital.payload["kind"] == "authorized_capital"
    assert capital.payload["decision_date"] == "2019-01-25"
    assert capital.payload["additional_decision_date"] == "2019-01-31"

    acquisition = _parser_134_events(
        "784a8c82-31a5-4eb6-8f14-9f715fcea100",
        "de.text.intended_sole_proprietorship_acquisition_fragment.v1",
    )[0]
    assert acquisition.payload["source"] == "Buuregarte Boog"
    assert acquisition.payload["source_place"] == "Hünenberg"
    assert acquisition.payload["included_asset"] == "Grundstück GS Nr. 2, Hünenberg"
    assert acquisition.payload["maximum_price"] == "2'000'000.00"
    assert acquisition.payload["balance_sheet_pending"] is True

    for stem in (
        "74974ab1-c02e-4c41-9410-ef386153d33b",
        "7a8af913-19d7-43f8-98f3-d451797e6aa7",
    ):
        ancillary = _parser_134_events(
            stem, "fr.text.ancillary_obligations_negated_variant.v1"
        )[0]
        assert ancillary.payload["kind"] == "ancillary_obligations"
        assert ancillary.payload["action"] == "correction_negated"

    audit = _parser_134_events(
        "7c4c10d9-124a-47da-8be0-52ccae953817",
        "de.text.audit_waiver_entry_removed_auditor_added.v1",
    )
    waiver = next(event for event in audit if event.event_type == "audit_requirement_changed")
    auditor = next(event for event in audit if event.event_type == "officer_changed")
    assert waiver.payload["entry_date"] == "2016-10-12"
    assert waiver.payload["limited_audit_waived"] is False
    assert auditor.person_key == "uid:CHE-320.207.362"
    assert auditor.payload["place"] == "Fribourg"


