def test_parser_135_status_statutes_branch_and_capital_are_structured():
    restriction = _parser_135_events(
        "7167ce29-ba6f-4730-a2d0-c4a90bae009d",
        "fr.text.share_transfer_restriction_statutory_derogation.v1",
    )[0]
    assert restriction.payload["kind"] == "share_transfer_restriction"
    assert restriction.payload["statutory_derogation"] is True

    foundation = _parser_135_events(
        "77128a1e-8caf-4a17-9f44-447903076938",
        "fr.persons.foundation_dissolved_five_liquidators.v1",
    )
    dissolved = next(event for event in foundation if event.event_type == "status_changed")
    liquidators = [event for event in foundation if event.event_type == "officer_changed"]
    assert dissolved.payload["decision_date"] == "2024-03-14"
    assert len(liquidators) == 5
    assert {event.payload["name"] for event in liquidators} == {
        "Paizi Dhaim Eugenia",
        "Potter Christopher",
        "Eurin Rodolphe",
        "Lufkin Thomas",
        "Bensouda Mehdi",
    }

    deletion = _parser_135_events(
        "89009abf-992b-487a-b7ba-8107201b0ba3",
        "de.text.art_938a_deletion_postponed.v1",
    )[0]
    assert deletion.payload["procedure_completed"] is True
    assert deletion.payload["reason"] == "missing_tax_authority_consents"

    branch = _parser_135_events(
        "8d157f8b-fced-416a-9ecb-9ce5db087ef8",
        "fr.text.branch_name_changed.v1",
    )[0]
    assert branch.payload["scope"] == "branch"
    assert branch.payload["to"] == (
        "Axians Schweiz SA (Axians Schweiz AG) (Axians Svizzera SA) "
        "(Axians Switzerland Ltd)"
    )

    capital = _parser_135_events(
        "8e0a2207-25e3-4bea-bdfb-b872f673f8c1",
        "de.text.head_office_capital_unlabeled_paid_in.v1",
    )[0]
    assert capital.payload["from_nominal"] == "12'401.00"
    assert capital.payload["to_nominal"] == "12'411.00"
    assert capital.payload["from_paid"] == "12'401.00"
    assert capital.payload["to_paid"] == "12'411.00"


def test_parser_135_board_signing_and_corrections_are_structured():
    foundation_signer = _parser_135_events(
        "83ff1f75-3eba-43ab-83f3-8e08a4cd1712",
        "fr.persons.foundation_member_signing_granted.v1",
    )[0]
    assert foundation_signer.payload["name"] == "Extermann Laurent"
    assert foundation_signer.signing == "Kollektivunterschrift zu zweien"

    board = _parser_135_events(
        "881dddc5-a676-486f-9f5b-34c5d61d9725",
        "fr.persons.board_replaced_four_members.v1",
    )
    removed = [event for event in board if event.event_type == "officer_removed"]
    added = [event for event in board if event.event_type == "officer_changed"]
    assert {event.payload["name"] for event in removed} == {"Balzli Urs", "Dufond François"}
    assert len(added) == 4
    president = next(event for event in added if event.payload["name"] == "Gautschi Matthias Andreas")
    assert president.role == "président du conseil"
    assert president.payload["place"] == "Sigriswil"

    correction = _parser_135_events(
        "8aa849f2-0289-44ca-acb0-7de354c86b0a",
        "fr.persons.incorrect_board_membership_corrected.v1",
    )[0]
    assert correction.payload["name"] == "Gros Alain"
    assert correction.payload["role_applies"] is False
    assert correction.signing == "Einzelunterschrift"

    procurations = _parser_135_events(
        "8ace550b-f599-4fc3-a00b-26fe9e90a1bb",
        "fr.persons.four_restricted_procurations.v1",
    )
    assert len(procurations) == 4
    assert all(event.signing == "Kollektivprokura zu zweien" for event in procurations)
    assert all(event.payload["cannot_sign_with_each_other"] is True for event in procurations)
    assert procurations[-1].payload["place"] == "Châtel-Saint-Denis"

    signers = _parser_135_events(
        "91c05642-2e17-4c24-8ac0-23c2def09097",
        "fr.persons.five_signers_one_domicile_changed.v1",
    )
    fischer = next(event for event in signers if event.payload["name"] == "Fischer Rudolf W.")
    assert fischer.payload["place"] == "Bergdietikon"
    assert fischer.payload["domicile_changed"] is True

    directors = _parser_135_events(
        "97163be8-501e-4d97-bfec-64383d900f22",
        "fr.persons.directors_appointed_board_members.v1",
    )
    assert {event.payload["name"] for event in directors} == {
        "Gavillet Michel",
        "Largeteau Clémentine",
    }
    assert all(event.payload["previous_role"] == "directeur" for event in directors)


