def test_parser_141_share_transfers_are_structured():
    removed_and_buyer = _parser_141_events(
        "2215bb89-7d0a-45d5-96d4-74189996f194",
        "fr.persons.two_managers_removed_shares_to_existing_manager.v1",
    )
    removed = [event for event in removed_and_buyer if event.event_type == "officer_removed"]
    assert {event.payload["name"] for event in removed} == {
        "Pighetti Ugo",
        "Vitale Daniele",
    }
    assert all(event.payload["shares_transferred"] == 140 for event in removed)
    buyer = next(event for event in removed_and_buyer if event.event_type == "officer_changed")
    assert buyer.payload["name"] == "Vitale Vincenzo"
    assert buyer.payload["shares_count"] == 420
    assert buyer.payload["capital"] == "42'000"

    didisheim = _parser_141_events(
        "23b9d8a3-0d93-42d8-aa43-a168c8d4f3b8",
        "fr.persons.manager_president_transfer_to_new_manager.v2",
    )
    by_name = {event.payload["name"]: event for event in didisheim}
    assert by_name["Didisheim Edna"].payload["shares_count"] == 350
    assert by_name["Didisheim Edna"].role == "associée-gérante et présidente"
    assert by_name["Peclard Annabelle"].payload["shares_received"] == 150
    assert by_name["Peclard Annabelle"].payload["place"] == "Bourg-en-Lavaux"

    quintino = _parser_141_events(
        "3051d5c5-0a83-405f-92cc-43d5cef9929e",
        "fr.persons.manager_president_transfer_to_new_manager.v2",
    )
    by_name = {event.payload["name"]: event for event in quintino}
    assert by_name["Quintino Guido"].payload["shares_count"] == 10
    assert by_name["Petrusova Monika"].payload["shares_received"] == 10
    assert by_name["Petrusova Monika"].payload["heimat"] == "Slovaquie"


