def test_parser_145_reinstatements_and_corrections_are_structured():
    cleanup = _parser_145_events(
        "771996e0-12a7-497b-a00c-c5f7d04916ca",
        "de.text.company_reinstated_public_register_cleanup.v1",
    )[0]
