def test_parser_145_share_transfers_are_structured():
    foreign = _parser_145_events(
        "78758a16-f5ce-483e-91f3-8a9516d3cf1a",
        "fr.persons.foreign_associate_transfer_to_two.v1",
    )
    adar = next(event for event in foreign if event.payload["name"] == "ADAR CAPITAL")
    samelia = next(event for event in foreign if event.payload["name"] == "SAMELIA CAPITAL")
    moria = next(event for event in foreign if event.payload["name"] == "MORIA CAPITAL")
    assert adar.payload["registry_id"] == "B187886"
    assert adar.payload["shares_before"] == 200
    assert adar.payload["shares_count"] == 85
    assert samelia.payload["shares_received"] == 85
    assert moria.payload["shares_received"] == 30

    categorized = _parser_145_events(
        "90fc480b-08ea-4148-93ce-dd11b1799b00",
        "fr.persons.two_associates_transfer_categorized_shares.v1",
    )
    honeywell = next(
        event for event in categorized
        if event.payload["name"] == "Honeywell International Holding GmbH"
    )
    assert honeywell.person_key == "uid:CHE-434.282.850"
    assert honeywell.payload["shares"] == [
        {"count": 938, "category": "A", "nominal": "100", "currency": "CHF"},
        {"count": 181, "category": "C", "nominal": "100", "currency": "CHF"},
        {"count": 2533, "category": "ordinary", "nominal": "100", "currency": "CHF"},
    ]

    managers = _parser_145_events(
        "9131e245-5a44-4d6a-959d-2729021137d7",
        "fr.persons.associate_transfer_to_three_managers.v1",
    )
    seller = next(event for event in managers if event.payload["name"] == "Poli Bernard")
    buyers = [event for event in managers if event.payload["name"] != "Poli Bernard"]
    assert seller.payload["shares_before"] == 200
    assert seller.payload["shares_transferred"] == 60
    assert seller.payload["shares_count"] == 140
    assert {event.payload["shares_count"] for event in buyers} == {20}
    assert sum(event.signing == "Einzelunterschrift" for event in buyers) == 1
    assert sum(event.signing == "Kollektivunterschrift zu zweien" for event in buyers) == 2


