def test_parser_151_foundation_board_and_presidency_changes_are_structured():
    foundation = _parser_151_events(
        "1a3cf93d-e9d4-4be0-8599-302f97e16cc3",
        "fr.persons.foundation_board_role_changes_and_new_members.v1",
    )
    by_name = {event.payload["name"]: event for event in foundation}
    assert set(by_name) == {
        "Tournaire Claude", "Reiser Christian", "Vallée Jean-Paul", "Peyvel Rodolphe"
    }
    assert by_name["Tournaire Claude"].payload["previous_role"] == "président"
    assert by_name["Tournaire Claude"].role == "vice-président du conseil de fondation"
    assert by_name["Vallée Jean-Paul"].payload["place"] == "Genève"
    assert by_name["Vallée Jean-Paul"].payload["origin"] == "La Sagne"
    assert by_name["Peyvel Rodolphe"].payload["country"] == "F"
    assert {event.signing for event in foundation} == {
        "Kollektivunterschrift zu zweien"
    }

    swapped = _parser_151_events(
        "263181f9-c877-4c9b-9299-7da2d65f20ab",
        "fr.persons.board_presidency_swapped.v1",
    )
    by_name = {event.payload["name"]: event for event in swapped}
    assert by_name["Bouchard Cédric"].role == "président"
    assert by_name["Bouchard Cédric"].payload["previous_role"] == "vice-président"
    assert by_name["Perez Galvez Salvador"].role == "vice-président"
    assert by_name["Perez Galvez Salvador"].payload["previous_role"] == "président"


