def test_parser_151_bankruptcy_composition_and_dissolution_are_structured():
    bankruptcy = _parser_151_events(
        "231175bd-2a74-407e-95c5-6785841a7998",
        "de.text.owner_bankruptcy_appeal_entry_removed_by_order.v1",
    )[0]
    assert bankruptcy.payload["scope"] == "owner"
    assert bankruptcy.payload["action"] == "suspended_on_appeal"
    assert bankruptcy.payload["decision_date"] == "2019-03-27"
    assert bankruptcy.payload["bankruptcy_date"] == "2019-02-05"
    assert bankruptcy.payload["effective_time"] == "14:00"
    assert bankruptcy.payload["bankruptcy_entry_removed"] is True

    composition = _parser_151_events(
        "29a37cb5-0042-4cee-8af0-dd022f98e5d8",
        "de.text.composition_agreement_confirmed_with_removed_moratorium.v1",
    )
    by_kind = {event.payload["kind"]: event for event in composition}
    assert by_kind["composition_agreement_confirmed"].payload["decision_date"] == (
        "2019-04-16"
    )
    moratorium = by_kind["composition_moratorium_granted"]
    assert moratorium.payload["action"] == "removed"
    assert moratorium.payload["duration_months"] == 6
    assert moratorium.payload["until"] == "2019-02-28"

    dissolution = _parser_151_events(
        "2aebe397-3964-43b0-b8f1-fe2ca41aad54",
        "fr.text.association_dissolution_two_liquidators.v1",
    )
    status = next(event for event in dissolution if event.event_type == "status_changed")
    assert status.payload["kind"] == "dissolution"
    assert status.payload["date"] == "2019-01-17"
    liquidators = [event for event in dissolution if event.event_type == "officer_changed"]
    assert {event.payload["name"] for event in liquidators} == {
        "Ladak Firoz", "Chevalley Pascal"
    }
    assert {event.signing for event in liquidators} == {"Einzelunterschrift"}
    assert next(
        event for event in liquidators if event.payload["name"] == "Ladak Firoz"
    ).payload["domicile_changed"] is True


