def test_parser_161_legal_status_and_capital_changes_are_structured():
    bankruptcy = _parser_161_events(
        "000797ef-55d5-4be0-ae82-e2ca6a28c7cf",
        "de.text.head_office_bankruptcy_opening_revoked.v1",
    )[0]
    assert bankruptcy.payload["decision_date"] == "2019-04-17"
    assert bankruptcy.payload["bankruptcy_date"] == "2019-02-26"
    assert bankruptcy.payload["registration_continued"] is True

    resumed = _parser_161_events(
        "04d59d1a-852e-46f2-9323-5c9ae1edfc65",
        "de.text.bankruptcy_suspension_revoked.v1",
    )[0]
    assert resumed.payload["kind"] == "bankruptcy_proceedings_resumed"
    assert resumed.payload["previous_decision_date"] == "2019-04-25"

    resolutions = _parser_161_events(
        "00ca49aa-0659-4cc6-a18c-73bcbc58805b",
        "de.text.board_election_resolutions_nullified_no_changes.v1",
    )[0]
    assert resolutions.payload["persons"] == ["Sophie Straumann", "Daniel Hofmann"]
    assert resolutions.payload["registry_entries_changed"] is False

    capital = _parser_161_events(
        "07815634-a326-4435-870c-54a4e8990855",
        "fr.text.authorized_removed_and_conditional_modified.v1",
    )
    by_kind = {event.payload["kind"]: event for event in capital}
    assert by_kind["authorized_capital_clause"].payload["action"] == "removed"
    conditional = by_kind["conditional_capital_clause"]
    assert conditional.payload["action"] == "modified"
    assert conditional.payload["decision_date"] == "2019-05-14"


