def test_parser_182_capital_and_profit_certificate_changes_are_structured():
    global_id = _parser_182_events(
        "c91bad77-45da-41aa-8c66-96a731aa6d5b",
        "fr.text.name_split_participation_clauses.v1",
    )
    split = next(event for event in global_id if event.payload.get("kind") == "registered_share_split")
    assert split.payload["from_count"] == 1000
    assert split.payload["to_count"] == 10000000
    assert split.payload["capital_total"] == "100000"
    assert split.payload["transfer_restricted"] is True
    clauses = [event for event in global_id if "capital_clause" in event.payload.get("kind", "")]
    assert {event.payload["kind"] for event in clauses} == {
        "authorized_participation_capital_clause",
        "conditional_participation_capital_clause",
    }
    assert all(event.payload["decision_date"] == "2019-05-24" for event in clauses)

    first_certificates = _parser_182_events(
        "cc5b546b-5724-486a-bd35-e1b6d7e0f343",
        "de.text.profit_participation_certificates_max_remuneration.v1",
    )[0]
    corrected_certificates = _parser_182_events(
        "d395de41-9e89-4f58-b500-9428ac455700",
        "de.text.profit_participation_certificates_max_remuneration.v1",
    )[0]
    assert first_certificates.payload["count"] == 10
    assert first_certificates.payload["maximum_annual_remuneration"] == "2'000'000.00"
    assert corrected_certificates.payload["count"] == 100
    assert corrected_certificates.payload["maximum_annual_remuneration"] == "200'000.00"

    recapitalization = _parser_182_events(
        "d6193313-6d82-488c-b24f-d8123e4be489",
        "de.text.capital_reduction_reincrease_setoff.v1",
    )[0]
    assert recapitalization.payload["destroyed_shares_count"] == 3000
    assert recapitalization.payload["issued_shares_count"] == 3000
    assert recapitalization.payload["setoff_amount"] == "3'000'000.00"
    assert recapitalization.payload["nominal_capital_unchanged"] is True

    removed = _parser_182_events(
        "da9c08bb-7a53-449b-b784-bb40cd935abc",
        "de.text.bearer_profit_certificates_removed.v1",
    )[0]
    assert removed.payload["count"] == 316
    assert removed.payload["action"] == "removed"


