    merger = _parser_183_events(
        "df80519e-51a9-4825-9381-96af62654878",
        "it.text.merger_no_capital_safeguard.v1",
    )[0]
    assert merger.payload["absorbed_uid"] == "CHE-101.583.852"
    assert merger.payload["assets"] == "14'169'559.00"
    assert merger.payload["liabilities"] == "3'233'391.00"
    assert merger.payload["capital_increase"] is False
    assert merger.payload["shares_allocated"] is False

    corrected_capital = _parser_183_events(
        "e6b6bd94-fd73-4e6a-b5f5-2c04f4f4d246",
        "de.text.statutes_date_capital_corrected.v1",
    )
    correction = next(event for event in corrected_capital if event.event_type == "publication_corrected")
    capital = next(event for event in corrected_capital if event.event_type == "capital_changed")
    assert correction.payload["previous_date"] == "2019-02-22"
    assert correction.payload["date"] == "2019-03-27"
    assert capital.payload["amount"] == "4'900'000.00"
