def test_parser_185_share_changes_are_balanced_and_structured():
    manager_transfer = _parser_185_events(
        "0972593a-d74c-46eb-8c8d-e11459fde284",
        "fr.persons.manager_transfer_to_new_manager_president.v1",
    )
    seller = next(event for event in manager_transfer if event.payload["name"] == "Pittet Anne-Claire")
    buyer = next(event for event in manager_transfer if event.payload["name"] == "King Jessica")
    assert seller.payload["shares_before"] == 200
    assert seller.payload["shares_transferred"] == 100
    assert seller.payload["shares_count"] == 100
    assert buyer.role == "associée-gérante présidente"
    assert buyer.signing == "Kollektivunterschrift zu zweien"

    mass_transfer = _parser_185_events(
        "09bf5940-22f6-4444-983e-a12a9af5d80a",
        "fr.persons.mass_share_transfer.v1",
    )
    mass_seller = next(event for event in mass_transfer if event.payload["name"] == "Martin Didier")
    recipients = [event for event in mass_transfer if event is not mass_seller]
    assert mass_seller.payload["shares_before"] == 47
    assert mass_seller.payload["shares_transferred"] == 30
    assert mass_seller.payload["shares_count"] == 17
    assert mass_seller.payload["recipient_count"] == 12
    assert sum(event.payload["shares_received"] for event in recipients) == 30
    assert {event.payload["name"] for event in recipients} >= {
        "Baumgartner Philippe",
        "Koch Philippe",
        "Valsangiacomo Uberto",
    }

    existing = _parser_185_events(
        "190e2b2a-c4fd-4777-ba39-29175fb250fb",
        "fr.persons.existing_associate_share_transfer.v1",
    )
    assert {event.payload["shares_count"] for event in existing} == {15}
    assert sum(event.payload.get("shares_transferred", 0) for event in existing) == 5
    assert sum(event.payload.get("shares_received", 0) for event in existing) == 5


