def test_parser_189_capital_changes_are_structured():
    bands = _parser_189_events(
        "f217761a-9c0a-4010-976c-de149eb9658f",
        "de.text.capital_bands_and_four_clauses.v1",
    )
    assert len(bands) == 6
    assert {(event.payload["kind"], event.payload["action"]) for event in bands} == {
        ("capital_band", "introduced"),
        ("authorized_capital_clause", "removed"),
        ("authorized_participation_capital_clause", "removed"),
        ("conditional_capital_clause", "modified"),
        ("conditional_participation_capital_clause", "modified"),
    }
    assert {event.payload["decision_date"] for event in bands} == {"2023-06-20"}
    assert {event.payload["previous_decision_date"] for event in bands} == {
        "2021-06-11"
    }

    replacement = _parser_189_events(
        "631fa2da-4d66-41e3-8e27-d594d11f9bd0",
        "fr.text.authorized_capital_clause_replaced.v1",
    )
    assert [event.payload["action"] for event in replacement] == [
        "removed",
        "introduced",
    ]
    assert replacement[0].payload["previous_decision_date"] == "2017-07-13"
    assert {event.payload["decision_date"] for event in replacement} == {"2019-05-20"}

    clauses = _parser_189_events(
        "634bf41f-a264-416e-851b-602c14d3161a",
        "fr.text.four_capital_clauses.v1",
    )
    assert len(clauses) == 4
    assert {event.payload["decision_date"] for event in clauses} == {"2019-06-25"}
    assert any(
        event.payload["kind"] == "conditional_participation_capital_clause"
        and event.payload["action"] == "introduced"
        for event in clauses
    )


