def test_parser_190_share_and_capital_changes_are_structured():
    transfer = _parser_190_events(
        "6b8e5455-bc14-40c0-bc22-c07125eaa12c",
        "fr.persons.manager_transfer_to_unsigned_associate.v1",
    )
    seller = next(event for event in transfer if event.payload["name"] == "Correia de Matos Agostinho")
    buyer = next(event for event in transfer if event.payload["name"] == "Correia de Matos José Manuel")
    assert seller.payload["shares_before"] == 200
    assert seller.payload["shares_transferred"] == 39
    assert seller.payload["shares_count"] == 161
    assert buyer.payload["shares_received"] == buyer.payload["shares_count"] == 39
    assert buyer.payload["without_signature"] is True
    assert buyer.payload["origin"] == "Portugal"
    assert buyer.payload["place"] == "Echandens"

    capital = _parser_190_events(
        "6c2caf3f-7228-4178-a67c-2068cffd8fe6",
        "fr.text.share_restriction_removed_and_capital.v1",
    )
    restriction = next(event for event in capital if event.payload["kind"] == "share_transfer_restriction")
    composition = next(event for event in capital if event.payload["kind"] == "share_capital")
    assert restriction.payload["action"] == "removed"
    assert composition.payload["total"] == "100'000"
    assert composition.payload["shares_count"] == 100
    assert composition.payload["share_nominal"] == "1'000"
    assert composition.payload["fully_paid"] is True

    renamed = _parser_190_events(
        "7ed0b76b-1a62-448c-85c7-d6773f4e0ddf",
        "fr.persons.renamed_associate_pair_and_transfer.v1",
    )
    dino = next(event for event in renamed if event.payload["name"] == "Bekteshi Dino")
    shaban = next(event for event in renamed if event.payload["name"] == "Bekteshi Shaban")
    assert dino.payload["previous_name"] == "Bekteshi Hajredin"
    assert dino.payload["shares_count"] == 1
    assert shaban.payload["shares_before"] == 50
    assert shaban.payload["shares_received"] == 49
    assert shaban.payload["shares_count"] == 99
    assert {event.signing for event in renamed} == {"Einzelunterschrift"}


