def test_parser_192_share_transfers_preserve_counts_and_restrictions():
    transfer = _parser_192_events(
        "9482ddae-cbc8-47a3-97eb-69638654dc9e",
        "fr.persons.manager_transfer_and_presidency.v1",
    )
    seller = next(event for event in transfer if event.payload["name"] == "Teodori Sara")
    buyer = next(
        event for event in transfer if event.payload["name"] == "Wellinger Marie-Pascale"
    )
    assert seller.role == "associée-gérante présidente"
    assert seller.payload["shares_before"] == 200
    assert seller.payload["shares_transferred"] == 100
    assert seller.payload["shares_count"] == 100
    assert buyer.role == "associée-gérante"
    assert buyer.payload["shares_received"] == buyer.payload["shares_count"] == 100
    assert buyer.signing == "Einzelunterschrift"

    reallocated = _parser_192_events(
        "96706066-2f9a-4217-aef5-94cc17b7c68d",
        "fr.persons.six_associates_shares_reallocated.v1",
    )
    counts = {event.payload["name"]: event.payload["shares_count"] for event in reallocated}
    assert counts == {
        "Lamaj Adrien": 42,
        "Skalli Leïla": 42,
        "Bordes Christophe": 42,
        "Lavialle Antoine": 38,
        "Sachetat Guillaume François Pierre": 6,
        "Fongaufier Rémi": 30,
    }
    fongaufier = next(
        event for event in reallocated if event.payload["name"] == "Fongaufier Rémi"
    )
    assert fongaufier.payload["new_associate"] is True
    assert fongaufier.payload["without_signature"] is True
