def test_parser_201_status_share_and_asset_transfers_are_structured():
    bankruptcy = _parser_201_events(
        "4f9fd823-2655-4bbc-a433-968229815dc9",
        "de.text.bankruptcy_reopened_with_effective_time.v1",
    )[0]
    assert bankruptcy.payload["action"] == "reopened"
    assert bankruptcy.payload["decision_date"] == "2019-08-09"
    assert bankruptcy.payload["effective_time"] == "11:15"
    assert bankruptcy.payload["previous_decision_date"] == "2019-07-12"

    transfers = _parser_201_events(
        "5028009b-b0b5-4341-b5b1-fe8ec1c5bbb6",
        "fr.persons.three_associate_transfers_without_signing.v1",
    )
    transfer_by_name = {event.payload["name"]: event for event in transfers}
    seller = transfer_by_name["Nguyen Thi Thuy Nhu"]
    assert seller.payload["shares_before"] == 20
    assert seller.payload["shares_transferred"] == 9
    assert seller.payload["shares_count"] == 11
    buyers = [event for event in transfers if event is not seller]
    assert all(event.payload["shares_received"] == 3 for event in buyers)
    assert all(event.payload["without_signature"] is True for event in buyers)

    reinstatement = _parser_201_events(
        "502ed386-04d4-470c-8d61-012b1b1e2654",
        "de.text.company_reinstated_with_liquidator_and_address.v1",
    )
    status = next(event for event in reinstatement if event.event_type == "status_changed")
    liquidator = next(
        event for event in reinstatement if event.event_type == "officer_changed"
    )
    address = next(event for event in reinstatement if event.event_type == "address_changed")
    assert status.payload["reason"] == "liquidation"
    assert status.payload["decision_date"] == "2019-07-02"
    assert liquidator.payload["name"] == "Cowell, Rosmarie"
    assert liquidator.role == "Liquidatorin"
    assert address.payload["to"].endswith("9000 St. Gallen")

    assets = _parser_201_events(
        "557d3aa1-f505-4f86-a59b-0a3ca197f3e7",
        "de.text.two_business_unit_asset_transfers_long_term_loans.v1",
    )
    assets_by_unit = {event.payload["business_unit"]: event for event in assets}
    assert assets_by_unit["Landtechnik"].payload["consideration_amount"] == "800'000.00"
    assert assets_by_unit["Mechanik"].payload["consideration_amount"] == "400'000.00"
    assert all(
        event.payload["recipient_uid"] == "CHE-290.787.817" for event in assets
    )

    manager_transfer = _parser_201_events(
        "56a48394-a347-4e41-87f7-1f3e82d32de9",
        "fr.persons.manager_transfer_to_new_manager_president.v1",
    )
    manager_by_name = {event.payload["name"]: event for event in manager_transfer}
    assert manager_by_name["Ates Delil"].payload["shares_count"] == 10
    assert manager_by_name["Ukaj Timothée"].payload["shares_received"] == 10
    assert manager_by_name["Ukaj Timothée"].role == "associé-gérant et président"
    assert manager_by_name["Ukaj Timothée"].signing == "Einzelunterschrift"


