    assert by_name["Gottofrey Cédric"].payload["shares_transferred"] == 40
    assert by_name["Mivelaz Marcel"].payload["shares_count"] == 60
    assert by_name["Mivelaz Marcel"].signing == "Kollektivunterschrift zu zweien"
    assert by_name["Hoti Lulzim"].payload["shares_count"] == 20
    assert by_name["Hoti Lulzim"].payload["later_spelling"] == "Hoti Luzlim"

