def test_parser_210_people_and_corrections_are_structured():
    president = _parser_210_events(
        "2133546f-a6d6-40ed-9f51-1076bac403e3",
        "fr.persons.administrator_presidency_supplement.v1",
    )[0]
    assert president.payload["name"] == "Bennet Laurent"
    assert president.payload["notice_ref"] == "0/1004637235"
    assert "président" in president.role

    committee = _parser_210_events(
        "22053594-0b07-40a3-a780-ddd05051fc36",
        "fr.persons.two_new_committee_members.v1",
    )
    by_name = {event.payload["name"]: event for event in committee}
    assert by_name["Basler Eric"].payload["origin"] == "Zeihen"
    assert "secrétaire" in by_name["Basler Eric"].role
    assert by_name["Dozio Jacques"].payload["place"] == "Meyrin"
    assert all(event.signing == "Kollektivunterschrift zu zweien" for event in committee)

    purpose = _parser_210_events(
        "263ec7d6-3155-462e-ac63-75108c4155e5",
        "fr.text.purpose_corrected.v1",
    )[0]
    assert "www.viniveritas.com" in purpose.payload["purpose"]
    assert purpose.payload["incorrect_published_text"] == "www.vinivetitas.com"

    name = _parser_210_events(
        "309e79c3-8558-44da-a4e0-2f56828317f0",
        "fr.persons.administrator_name_corrected_no_notice.v1",
    )[0]
    assert name.payload["name"] == "Shakhshir Tareq"
    assert name.payload["previous_name"] == "Shakhshir Toufiq"

    board = _parser_210_events(
        "346e65c0-2c6e-42d9-9a39-cdfdcd00d463",
        "de.persons.removed_and_two_new_board_members.v1",
    )
    by_name = {event.payload["name"]: event for event in board}
    assert by_name["Funke Stephan Josef Gerhard"].event_type == "officer_removed"
    assert "Präsident" in by_name["Aalto Esa-Matti"].role
    assert by_name["Müser Dominik"].payload["country"] == "DE"


def test_parser_210_merger_capital_clauses_and_bankruptcy_are_structured():
    merger = _parser_210_events(
        "291d576e-ac19-4af4-9668-418d45191e01",
        "it.text.merger_with_acquirer_own_shares.v1",
    )[0]
    assert merger.payload["absorbed_uid"] == "CHE-100.423.430"
    assert merger.payload["acquirer_own_registered_shares"] == 78_189
    assert merger.payload["capital_increase"] is False

    rejected = _parser_210_events(
        "2c9a99ba-763e-4a30-a8ca-ac34b1cd8e6c",
        "de.text.bankruptcy_petition_rejected_after_payment.v1",
    )[0]
    assert rejected.payload["action"] == "rejected"
    assert rejected.payload["reason"] == "subsequent_payment"
    assert rejected.payload["previous_decision_date"] == "2019-08-19"

    clauses = _parser_210_events(
        "2d3f172e-708f-4550-9c96-ddc102803ff9",
        "fr.text.authorized_and_conditional_capital_introduced.v1",
    )
    by_kind = {event.payload["kind"]: event for event in clauses}
    assert by_kind["authorized_capital_clause"].payload["decision_date"] == "2019-09-10"
    assert by_kind["conditional_capital_clause"].payload["details_in_statutes"] is True

    citation = _parser_210_events(
        "32e4236b-1a48-4212-ada3-ddf69d13adc6",
        "de.text.shab_citation_corrected_reference.v1",
    )[0]
    assert citation.payload["previous_issue"] == 171
    assert citation.payload["issue"] == 170
    assert citation.payload["publication_ref"] == "1004708464"

    bankruptcy = _parser_210_events(
        "32f978fe-99ac-49b6-bae0-98c714857b6e",
        "de.text.bankruptcy_opened_dissolution.v1",
    )[0]
    assert bankruptcy.payload["effective_date"] == "2019-09-03"
    assert bankruptcy.payload["effective_time"] == "08:29"
    assert bankruptcy.payload["dissolved"] is True


