def test_parser_211_capital_changes_are_structured():
    participation = _parser_211_events(
        "07772c68-71b1-4f21-8071-6c6d0f6dcbe3",
        "fr.text.conditional_participation_capital_increase.v1",
    )[0]
    assert participation.payload["clause_last_modified"] == "2023-12-15"
    assert participation.payload["issued_participation_certificates"] == 664
    assert participation.payload["participation_certificates"] == 9_997
    assert participation.payload["total"] == "999'700"

    conditional = _parser_211_events(
        "1e1b25ac-9070-4787-a126-c2a10b9d2991",
        "fr.text.conditional_share_capital_clause_no_details.v1",
    )[0]
    assert conditional.payload["decision_date"] == "2024-11-26"
    assert conditional.payload["action"] == "introduced"

    authorized = _parser_211_events(
        "3aa60b00-77ec-47d8-af0f-07770e677c54",
        "de.text.expired_and_new_authorized_capital_typo.v1",
    )
    by_action = {event.payload["action"]: event for event in authorized}
    assert by_action["removed"].payload["reason"] == "time_limit_expired"
    assert by_action["introduced"].payload["decision_date"] == "2019-08-20"


