def test_parser_241_share_transfers_are_structured_and_balanced():
    transfer = _parser_241_events(
        "d20b5512-1642-438f-8a60-2a0d0c322844",
        "fr.persons.share_transfer_new_unsigned_associate.v1",
    )
    gashi = next(event for event in transfer if event.payload["name"] == "Gashi Florim")
    yaroslavska = next(
        event for event in transfer if event.payload["name"] == "Yaroslavska Iryna"
    )
    assert gashi.payload["previous_shares_count"] == 20
    assert gashi.payload["shares_count"] == 10
    assert yaroslavska.payload["shares_count"] == 10
    assert yaroslavska.payload["without_signature"] is True

    multi = _parser_241_events(
        "df854064-328c-49cc-a001-f6c3f539d311",
        "fr.persons.two_managers_transfer_to_three_associates.v1",
    )
    assert {event.payload["name"] for event in multi} == {
        "Dragos Iulian",
        "Dotta Mirco",
        "Ciubotariu Ciprian-Dan-Alexandru",
        "Odersky Martin",
        "Stieger François",
    }
    sellers = [event for event in multi if event.role == "associé-gérant"]
    buyers = [event for event in multi if event.role == "associé"]
    assert all(event.payload["shares_count"] == 97 for event in sellers)
    assert all(event.payload["shares_count"] == 2 for event in buyers)

    single = _parser_241_events(
        "efafbc1c-320c-400f-8716-b29f966af237",
        "fr.persons.associate_transfer_to_new_unsigned_associate.v1",
    )
    assert {event.payload["shares_count"] for event in single} == {100}
    assert any(event.payload["name"] == "Chenard Bruno" for event in single)


