def test_parser_242_people_share_and_status_changes_are_structured():
    three_sellers = _parser_242_events(
        "00c8ce06-6ebf-49c3-9a19-e945839987d4",
        "fr.persons.three_managers_transfer_to_new_manager.v1",
    )
    pasche = next(event for event in three_sellers if event.payload["name"] == "Pasche Yves")
    assert pasche.payload["shares_count"] == 51
    assert pasche.signing == "Kollektivunterschrift zu zweien"
    assert all(
        event.payload["shares_count"] == 51
        for event in three_sellers
        if event.payload["name"] != "Pasche Yves"
    )

    committee = _parser_242_events(
        "f4d75e3e-59d8-4777-b26e-dd84a43098ea",
        "fr.persons.two_committee_members_with_cantons.v1",
    )
    assert {event.payload["residence_canton"] for event in committee} == {"GE", "ZH"}
    assert all(event.signing == "Einzelunterschrift" for event in committee)

    dissolution = _parser_242_events(
        "f6d1708a-23f8-4c93-aa59-95bf57c49bdf",
        "de.text.dissolution_and_associate_manager_liquidator.v1",
    )
    status = next(event for event in dissolution if event.event_type == "status_changed")
    liquidator = next(event for event in dissolution if event.person_key)
    assert status.payload["decision_date"] == "2019-11-05"
    assert "Liquidatorin" in (liquidator.role or "")
    assert liquidator.payload["shares_count"] == 20

    replacement = _parser_242_events(
        "fdf9ea75-2b9d-4f19-9eea-6aecf7c0a0f7",
        "fr.persons.foundation_board_replacement_no_signature.v1",
    )
    assert len([event for event in replacement if event.event_type == "officer_removed"]) == 6
    assert len([event for event in replacement if event.event_type == "officer_changed"]) == 3
    assert all(
        event.payload.get("without_signature") is True
        for event in replacement
        if event.event_type == "officer_changed"
    )

    liquidators = _parser_242_events(
        "ffd44ec6-5762-4160-afa1-18588f8c9452",
        "fr.persons.three_liquidators_appointed.v1",
    )
    assert {event.payload["name"] for event in liquidators} == {
        "Crot James", "Crot Pierre", "Gonet Nicolas"
    }
    assert all(event.signing == "Kollektivunterschrift zu zweien" for event in liquidators)


