    assert expired.payload["reason"] == "authorization_expired"

    clauses = _parser_244_events(
        "1d4483cf-cdc4-4ae3-9c1f-8454a48ee4e6",
        "de.text.authorized_capital_replaced_and_conditional_created.v1",
    )
    authorized = next(
        event for event in clauses
        if event.payload["kind"] == "authorized_capital_clause"
    )
    conditional = next(
        event for event in clauses
        if event.payload["kind"] == "conditional_capital_clause"
    )
    assert authorized.payload["replaced_authorization_dates"] == [
        "2018-04-06", "2018-05-16"
    ]
    assert authorized.payload["statutes_article"] == "Art. 4"
    assert conditional.payload["statutes_article"] == "Art. 4a"

