def test_parser_251_share_transfers_and_manager_roles_are_structured():
    jasari = _parser_251_events(
        "b1277d23-5462-4fdb-b6c2-058fdff8f2e9",
        "fr.persons.transfer_and_two_managers.v1",
    )
    amzi = next(event for event in jasari if event.payload["name"] == "Jasari Amzi")
    muharem = next(event for event in jasari if event.payload["name"] == "Jasari Muharem")
    assert amzi.payload["shares_before"] == 200
    assert amzi.payload["shares_count"] == 100
    assert amzi.role == "associé-gérant président"
    assert muharem.payload["shares_received"] == 100
    assert muharem.payload["shares_count"] == 100
    assert muharem.payload["place"] == "Bernex"
    assert all(event.signing == "Einzelunterschrift" for event in jasari)

    transfer = _parser_251_events(
        "b89caa9b-15a7-45ca-9eca-39aa07718e98",
        "fr.persons.manager_share_transfer_holdings.v1",
    )
    suter = next(event for event in transfer if event.payload["name"] == "Suter Teo")
    oliva = next(event for event in transfer if event.payload["name"] == "Oliva Agrippino")
    assert suter.payload["shares_before"] == 150
    assert suter.payload["shares_count"] == 134
    assert oliva.payload["shares_before"] == 50
    assert oliva.payload["shares_count"] == 66
    assert oliva.payload["powers_modified"] is True

    all_transferred = _parser_251_events(
        "b9fb65d3-ba84-49bd-bdf8-b8007f3a4f98",
        "fr.persons.two_managers_transfer_all_to_new_manager.v1",
    )
    removed = [event for event in all_transferred if event.event_type == "officer_removed"]
    assert {event.payload["shares_transferred"] for event in removed} == {1, 19}
    assert all(event.payload["shares_count"] == 0 for event in removed)
    turin = next(
        event for event in all_transferred if event.payload["name"] == "Turin Guy Daniel"
    )
    assert turin.payload["shares_received"] == 20
    assert turin.signing == "Einzelunterschrift"


