@pytest.mark.parametrize(("stem", "rule_id", "event_count"), PARSER_253_FIXTURES)
def test_parser_253_leftover_samples_are_fully_parsed_with_events(
    stem, rule_id, event_count
):
    result = _parse(stem)
    assert PARSER_VERSION == 253
    assert result.sub_rubric == "HR02"
    assert result.status == "FULLY_PARSED"
    assert result.leftover_text == ""
    assert len([event for event in result.events if event.rule_id == rule_id]) == event_count


def _parser_253_events(stem: str, rule_id: str):
    return [event for event in _parse(stem).events if event.rule_id == rule_id]


def test_parser_253_reinstatement_address_and_corrections_are_structured():
    reinstated = _parser_253_events(
        "e05ecb98-297e-481c-81fc-8e9aad396200",
        "fr.text.erroneous_official_deletion_reinstated.v1",
    )[0]
    assert reinstated.payload["reason"] == "erroneous_deletion"
    assert reinstated.payload["previous_deletion_legal_basis"] == "art. 159 al. 5 ORC"

    address = _parser_253_events(
        "e2a90324-6a25-4c9c-aab6-ed3b1e7946cf",
        "fr.text.other_address_corrected_without_notice.v1",
    )[0]
    assert address.payload["entry_date"] == "2019-12-06"
    assert address.payload["post_office_box"] == "Case postale 503"
    assert address.payload["postal_code"] == "1211"
    assert address.payload["place"] == "Genève 12"
    assert address.payload["previous_place"] == "Genève 2"

    communication = _parser_253_events(
        "e851cd1a-eeee-4de8-8a05-c2a7266b3496",
        "fr.text.shareholder_communication_recipient_corrected.v1",
    )[0]
    assert communication.payload["recipients"] == "shareholders"
    assert communication.payload["previous_recipients"] == "associates"
    assert communication.payload["notice_id"] == "1004729366"

    closure = _parser_253_events(
        "f2b8f24b-c770-474b-adb4-9914a1e0c7ae",
        "fr.text.bankruptcy_closure_date_correction_residue.v1",
    )[0]
    assert closure.payload["corrected_date"] == "2019-12-16"
    assert closure.payload["previous_published_date"] == "2019-11-22"
    assert closure.payload["previous_date_kind"] == "liquidation_suspension"


