def test_parser_253_capital_merger_and_share_transfer_are_structured():
    capital = _parser_253_events(
        "e8a89c9e-4f40-453e-84b6-ec8de21e257f",
        "fr.text.two_registered_share_classes_order_corrected.v1",
    )[0]
    assert capital.payload["share_classes"] == [
        {
            "count": 2211,
            "nominal": "10.00",
            "share_kind": "actions nominatives",
            "voting_privileged": True,
        },
        {
            "count": 1304,
            "nominal": "100.00",
            "share_kind": "actions nominatives",
            "voting_privileged": False,
        },
    ]
    assert capital.payload["previous_published_order"][0]["count"] == 1304

    merger = _parser_253_events(
        "ebd1a2f0-65d5-4c8b-9e02-845432400609",
        "it.text.merger_common_shareholder_no_capital_increase.v2",
    )[0]
    assert merger.payload["absorbed_name"] == "Manucasa SA"
    assert merger.payload["absorbed_uid"] == "CHE-109.613.072"
    assert merger.payload["assets"] == "1'019'469.00"
    assert merger.payload["liabilities"] == "480'983.00"
    assert merger.payload["capital_increase"] is False

    transfer = _parser_253_events(
        "edc1eb58-fad0-4246-b208-efbcd02bb0c0",
        "fr.persons.single_share_transfer_new_unsigned_associate.v2",
    )
    cafer = next(event for event in transfer if event.payload["name"] == "Yilmaz Cafer")
    ozkan = next(event for event in transfer if event.payload["name"] == "Özkan Yilmaz")
    assert cafer.payload["shares_before"] == 20
    assert cafer.payload["shares_count"] == 19
    assert ozkan.payload["shares_received"] == 1
    assert ozkan.payload["shares_count"] == 1
    assert ozkan.payload["without_signature"] is True


def test_parser_253_manager_and_foundation_groups_are_structured():
    bourgets = _parser_253_events(
        "ee7d75cc-4129-46a5-b290-ab753fc9986c",
        "fr.persons.two_associates_appointed_managers.v1",
    )
    jean_marie = next(
        event for event in bourgets if event.payload["name"] == "Bourget Jean-Marie"
    )
    david = next(event for event in bourgets if event.payload["name"] == "Bourget David")
    assert jean_marie.role == "associé-gérant président"
    assert david.payload["place"] == "Saint-Jean-de-Gonville"
    assert all(event.signing == "Kollektivunterschrift zu zweien" for event in bourgets)

    dissolution = _parser_253_events(
        "eeee461b-d9db-4263-ab34-7a5e65b64e36",
        "fr.text.foundation_dissolution_four_liquidators.v1",
    )
    status = next(event for event in dissolution if event.event_type == "status_changed")
    liquidators = [event for event in dissolution if event.person_key]
    assert status.payload["decision_date"] == "2019-11-11"
    assert {event.payload["name"] for event in liquidators} == {
        "Gretz Gabriel", "Masson Christine", "Arnoux Sébastien", "Rosay Alexandre"
    }
    assert all(event.signing == "Kollektivunterschrift zu zweien" for event in liquidators)

    foundation_members = _parser_253_events(
        "ef313560-9e49-489e-ad8d-8c0f5f8f4d71",
        "fr.persons.three_new_foundation_members_shared_place.v1",
    )
    assert {event.payload["origin"] for event in foundation_members} == {
        "Daillens", "Mörschwil", "Genève"
    }
    assert all(event.payload["place"] == "Lausanne" for event in foundation_members)
    assert all(
        event.signing == "Kollektivunterschrift zu zweien"
        for event in foundation_members
    )

    unsigned = _parser_253_events(
        "f0a6d6ac-946c-45f4-accd-3bcbe7d9d508",
        "fr.persons.two_board_members_without_signature_origins.v1",
    )
    assert {event.payload["name"] for event in unsigned} == {
        "Gaspoz Jean-Michel Thédule", "Kinkel Karen"
    }
    assert all(event.payload["without_signature"] is True for event in unsigned)
    assert all(event.signing is None for event in unsigned)
